-- Every proposed allocation carries an explicit, human-readable reason.
create or replace function public.admin_generate_dispatch_plan(p_reason text default 'Coordinator requested plan')
returns uuid language plpgsql security definer set search_path=public,extensions as $$
declare pid uuid;body jsonb;
begin if not private.is_admin()then raise exception'Administrator access required';end if;
 with ranked as(select i.*,row_number()over(order by i.priority_score desc,i.created_at)rn from public.incidents i where i.status in('reported','verified')and i.primary_incident_id is null),candidates as(select i.id incident_id,i.report_code,i.priority_level,i.priority_score,i.people_affected,t.id team_id,t.name team_name,round((st_distance(t.location,i.location)/1000)::numeric,1)distance_km,row_number()over(partition by i.id order by(t.capacity>=i.people_affected)desc,st_distance(t.location,i.location))choice,row_number()over(partition by t.id order by i.priority_score desc,i.created_at)team_use from ranked i left join public.rescue_teams t on t.status='available'and t.location is not null)
 select coalesce(jsonb_agg(jsonb_build_object('incident_id',incident_id,'report_code',report_code,'priority',priority_level,'score',priority_score,'team_id',case when choice=1 and team_use=1 then team_id end,'team_name',case when choice=1 and team_use=1 then team_name end,'straight_line_km',case when choice=1 and team_use=1 then distance_km end,'reason',case when choice=1 and team_use=1 then'Highest-priority incident matched to the nearest unused available team; capacity fit was preferred'end,'gap',case when team_id is null then'No available team'when not(choice=1 and team_use=1)then'Team capacity conflict — manual coordination required'else null end)order by priority_score desc),'[]'::jsonb)into body from candidates where choice=1 or team_id is null;
 update public.dispatch_plans set status='superseded'where status='draft';insert into public.dispatch_plans(trigger_reason,plan,created_by)values(trim(p_reason),body,auth.uid())returning id into pid;return pid;
end $$;
